  const VENUES = [
    {"id": "kilindi", "cat": "berth", "tier": "berth_top", "priority": 1, "name": "Kilindi Zanzibar", "short": "Kilindi", "neighborhood": "Kendwa · the north end, in 50 acres of garden", "maps": "https://www.google.com/maps/search/?api=1&query=Kilindi+Zanzibar+Kendwa", "badge": "DOMES", "tags": ["15 pavilion suites", "~75 min from ZNZ airport", "Plunge pool per pavilion"], "productTags": ["ABBA domes"], "hours": "Resort dining for residents: terrace and beach service; no à la carte street trade", "why": "Before Elewana took it over, Kilindi was designed as a private retreat for Benny Andersson of ABBA, and the plan still reads that way: fifteen domed pavilions spread over about fifty acres of hillside above the beach, each out of sight of the next, with slatted shutters where glass would be. Each pavilion has two rainwater plunge pools with a waterfall running between them. In 2025 Travel + Leisure readers voted it the number one resort in Africa.", "address": "Kendwa, Kaskazini A, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.762376, "lng": 39.291077, "category": "creme", "subcat": "THE DESTINATION ROOMS", "hook": "Fifteen white-domed pavilions on a hillside facing Tumbatu, built first as Benny Andersson's private retreat.", "person": "Originally built for Benny Andersson (ABBA); operated by Elewana / Minor Hotels", "signature": "Dinner on the sand below the domes at the end of the dry season", "verdict": "Go for the room and the quiet, not for the plate — the architecture is the reason and it is a real one.", "caveat": "Adults-only in practice and priced accordingly; not a walk-in dining room. Confirm dining access before you arrive if you are not a resident.", "price_range": "Resort rates only — dining included in the stay; no published à la carte", "reservation": "Residents only in practice — email ahead if you are not staying", "best_time": "Late afternoon into sunset — the domes take the western light", "dishes": [{"name": "Whatever the boat landed"}, {"name": "Swahili coconut curry"}], "signal_chip": {"label": "ABBA domes", "full": "Commissioned as a private residence for Benny Andersson of ABBA; now Elewana Kilindi Zanzibar", "cosign": "Operator's own listing (Minor Hotels), checked 22 Aug 2026"}, "web": "https://www.minorhotels.com/en/destinations/tanzania/zanzibar/elewana-kilindi-zanzibar", "charter": {"price": "Resort rates; dining included in the stay", "book": "Through Elewana / Minor Hotels · email ahead if you are not resident", "dress": "Smart resort", "warn": "Not a walk-in dining room — confirm access before you arrive", "fit": "Fifteen white domes in fifty acres, built as one man's private house."}},
    {"id": "zuri-zanzibar", "cat": "berth", "tier": "berth_top", "priority": 2, "name": "Zuri Zanzibar — Upendo", "short": "Zuri · Upendo", "neighborhood": "Kendwa · thirteen hectares behind the sand", "maps": "https://www.google.com/maps/search/?api=1&query=Zuri+Zanzibar+Kendwa", "badge": "DESIGN", "tags": ["55 cabanas + 5 villas", "13 ha", "Spice garden on site"], "productTags": ["EarthCheck Gold"], "hours": "Three restaurants: Upendo, Maisha and Bahari Grill & Bar; non-residents book", "why": "Zuri was drawn by the London architects Jestico + Whiles and became the first hotel anywhere to receive EarthCheck's Sustainable Design Gold certification. The brief included a spice garden that supplies the kitchens as well as the oils used in the massage rooms, so the cloves and lemongrass on the plate may have been growing a few hundred metres away. Dining splits three ways: Upendo above the resort, Maisha by the pool, and Bahari Grill & Bar on the beach.", "address": "Kendwa, Kaskazini A, Unguja", "phone": "+255 24 550 0111", "status": "confirmed", "statusChecked": "2026-10-07", "category": "creme", "subcat": "THE DESTINATION ROOMS", "hook": "A Kendwa design resort with three restaurants, a working spice garden and an audited green certificate.", "person": "Jestico + Whiles, architects (opened 2018)", "signature": "The last of the light from Bahari Grill, after the spice-garden tour", "verdict": "The best-run kitchen group on this stretch of sand, and the only one whose sustainability claim carries an audited certificate rather than a laminated card.", "caveat": "Non-residents are welcome but should book; this is resort pricing and the walk in from the village road is longer than it looks on a map.", "price_range": "Resort dining, upper band — half board included in most rates", "reservation": "Book ahead if you are not staying", "best_time": "Bahari Grill from about 17:00 for the western light; Maisha after dark", "dishes": [{"name": "Grills and small plates at Bahari"}, {"name": "Spice-garden plates"}, {"name": "Sugar-cane cocktails at Bahari"}], "signal_chip": {"label": "EarthCheck Gold", "full": "World's first gold EarthCheck certification for sustainable design; listed in the MICHELIN Guide hotel selection", "cosign": "EarthCheck and the resort's own site, checked 22 Aug 2026"}, "web": "https://www.zurizanzibar.com/culinary/", "charter": {"price": "Resort band — half board in most rates; non-residents pay à la carte", "book": "Book ahead if you are not staying", "dress": "Smart resort", "warn": "A long walk in from the village road — take a car after dark", "fit": "Three kitchens, a spice garden and the first gold EarthCheck for design."}},
    {"id": "emerson-hurumzi", "cat": "shop", "tier": "several", "priority": 42, "name": "Emerson on Hurumzi Tea House", "short": "Hurumzi", "neighborhood": "Stone Town · 236 Hurumzi Street, Kiponda", "maps": "https://www.google.com/maps/search/?api=1&query=Emerson+on+Hurumzi+Stone+Town+Zanzibar", "badge": "TAARAB", "tags": ["US$45 three courses", "One seating, 19:00", "Taarab most evenings"], "productTags": ["Rooftop"], "hours": "Dinner, one seating at 19:00, guests welcomed from 18:00 (own site via search index, Oct 2026)", "why": "Emerson on Hurumzi is three old merchants' houses joined together, one of them once owned by Zanzibar's archbishop, and its tea house is billed as the highest rooftop restaurant in Stone Town. There is one dinner seating, at seven. Diners sit on cushions at low tables and eat a set three courses of Zanzibari food with Persian and Omani threads while musicians from the Dhow Countries Music Academy play taarab, on most evenings.", "address": "236 Hurumzi Street, Kiponda, Stone Town", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -6.161015, "lng": 39.191008, "category": "creme", "subcat": "THE DESTINATION ROOMS", "hook": "A Stone Town rooftop dinner on floor cushions: US$45 for three courses, taarab musicians most evenings.", "signature": "Dinner cross-legged on the roof with the taarab going", "verdict": "Choose it for the music and the roof: taarab most evenings, cross-legged on rugs above the old town.", "caveat": "Floor seating on rugs — not for every back. Deposit required to confirm.", "price_range": "US$45 per person, three courses, drinks extra", "reservation": "Required with deposit", "best_time": "From 18:00; dinner at 19:00", "dishes": [{"name": "Three-course Swahili dinner"}, {"name": "Taarab, most evenings"}], "web": "https://emersonzanzibar.com/restaurants-in-stone-town/", "charter": {"price": "US$45 per person, three courses, drinks extra", "book": "Required, with a deposit · one seating at 19:00", "dress": "Smart casual — you will sit on the floor", "warn": "Floor seating on rugs: not for every back", "fit": "360 degrees of rooftops and taarab most evenings."}},
    {"id": "sexy-fish", "cat": "shop", "tier": "several", "priority": 19, "name": "Sexy Fish", "short": "Sexy Fish", "neighborhood": "Nungwi · at The Z Hotel, west-facing deck", "maps": "https://www.google.com/maps/search/?api=1&query=Sexy+Fish+Restaurant+Nungwi+Zanzibar", "badge": "SEAFOOD", "tags": ["West-facing deck", "African-European seafood", "Book ahead"], "productTags": ["Sunset side"], "hours": "Lunch and dinner", "why": "Sexy Fish is the beachfront restaurant of The Z Hotel on Nungwi's west beach. It is an open-air room with white tablecloths, and one reviewer described it as sitting above the ocean. The kitchen mixes African and European cooking around seafood: lobster tempura, crab curry, tuna ceviche, tandoori octopus with a mint dip. One guide records a format of one main course or three starters for US$36, which is the way to try more of the menu.", "address": "The Z Hotel, Nungwi, Kaskazini A", "phone": "+255 698 272 427", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.73029, "lng": 39.291821, "category": "rising", "subcat": "THE NEW WAVE", "hook": "The Z Hotel's beachfront restaurant in Nungwi: lobster tempura, crab curry and tuna ceviche, served al fresco.", "signature": "Tuna ceviche or lobster tempura on the west deck at the golden hour", "verdict": "The best cooking on the north tip outside the five-star resorts.", "caveat": "Book. Small deck, and the sunset tables go well ahead in high season. Some reviewers find the service slow: order early.", "price_range": "Upper mid", "reservation": "Essential for a sunset table", "best_time": "17:30 onward", "dishes": [{"name": "Tuna ceviche"}, {"name": "Lobster tempura"}, {"name": "Crab curry"}, {"name": "Cocktails on the deck"}], "web": "https://www.thezhotel.com/facilities/restaurants/sexy-fish", "charter": {"price": "Upper mid", "book": "Through The Z Hotel · essential for a sunset table in season", "dress": "Smart beach — no swimwear", "warn": "Small west-facing deck: the sunset tables go days ahead in high season; some reviewers find the service slow", "fit": "Tuna ceviche and lobster tempura on a west-facing deck over the water."}},
    {"id": "maisha-beach", "cat": "shop", "tier": "several", "priority": 20, "name": "Maisha Beach — Seafood & Cocktails", "short": "Maisha Beach", "neighborhood": "Nungwi · on the sand in front of Maisha Nungwi (formerly Aluna)", "maps": "https://www.google.com/maps/search/?api=1&query=Maisha+Beach+Nungwi+Zanzibar", "badge": "BEACH", "tags": ["Beach restaurant", "Maisha Nungwi", "Sunset side"], "productTags": ["Sunset side"], "hours": "Day into night; music nights vary with the season — ask before you plan around one", "why": "The hotel behind this beach kitchen used to trade as Aluna Nungwi, which is why the lane down to it is still called the Aluna road and why the booking sites still carry the old name in their links. The restaurant sits about 70 metres from the hotel, directly on the sand and facing west for the sunset. Visitor reviews single out a fish coconut curry and a tuna tartare; check the current menu and the weekly music nights before you go.", "address": "Aluna road, Nungwi, Kaskazini A", "phone": "+255 773 079 125", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.726843, "lng": 39.29362, "category": "rising", "subcat": "THE NEW WAVE", "hook": "The beach restaurant of the Maisha Nungwi hotel, on the sand at the north tip of the island.", "signature": "Grilled seafood on the sand as the light goes", "verdict": "The best food-to-atmosphere ratio on Nungwi sand, and the rare beach bar whose kitchen is not an afterthought.", "caveat": "Low season and Ramadan change the event programme — check before you plan a night around it.", "price_range": "Mid", "reservation": "Call or WhatsApp for a weekend table", "best_time": "Friday and Saturday from 20:00; any evening for the sunset", "dishes": [{"name": "Grilled seafood"}, {"name": "Fish coconut curry", "note": "as reviewers describe it, Oct 2026"}, {"name": "Fresh juices and smoothies"}], "web": "https://www.maishanungwi.com/restaurant", "charter": {"price": "Mid", "book": "Call or WhatsApp · same day is usually fine", "dress": "Beach casual", "warn": "Music nights change with the season and Ramadan — ask before you plan around one", "fit": "A beach restaurant with a real kitchen and a proper cocktail list."}},
    {"id": "yasa", "cat": "shop", "tier": "several", "priority": 66, "name": "Yasa Restaurant", "short": "Yasa", "neighborhood": "Nungwi · close to the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Yasa+Restaurant+Nungwi+Zanzibar", "badge": "FUSION", "tags": ["07:00–23:00", "Free shuttle", "Live music weekly"], "productTags": [], "hours": "Daily 07:00–23:00", "why": "Yasa is the restaurant of a boutique hotel a short walk from Nungwi beach, cooking across Asia and East Africa on one menu: a Malaysian laksa with seafood and house-made tofu at US$17, Arusha beef steak with butternut veloute at US$17.50, nasi goreng with organic vegetables, and a potato rosti eggs Benedict at US$11.50. It will send a car to collect you from anywhere in Nungwi.", "address": "Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.726473, "lng": 39.306444, "category": "rising", "subcat": "THE NEW WAVE", "hook": "A fusion kitchen in a Nungwi boutique hotel: laksa, Arusha steak, rosti Benedict, free pick-up.", "signature": "The laksa, or the rösti eggs Benedict if you get there in the morning", "verdict": "The one kitchen on this cape genuinely trying something, and the prices are honest about it.", "caveat": "Fusion is a risk register as much as a menu; the laksa and the steak are the safe bets. Event nights vary seasonally.", "price_range": "US$5–20 · mains US$17ish", "reservation": "Worth calling on music nights", "best_time": "Breakfast, or a music night", "dishes": [{"name": "Laksa", "note": "Malaysian seafood and noodle coconut curry — US$17"}, {"name": "Arusha steak, butternut velouté", "note": "US$17.50; mainland beef"}, {"name": "Potato rösti eggs Benedict", "note": "US$11.50 — the best breakfast plate up here"}, {"name": "Sticky pork belly ribs", "note": "US$17 — and note pork is not a given on this island"}], "web": "https://www.yasazanzibar.com/restaurant/"},
    {"id": "gold-zanzibar", "cat": "shop", "tier": "several", "priority": 4, "name": "Gold Zanzibar Beach House & Spa", "short": "Gold Zanzibar", "neighborhood": "Kendwa · on the sand, south end", "maps": "https://www.google.com/maps/search/?api=1&query=Gold+Zanzibar+Beach+House+Kendwa", "badge": "BEACH", "tags": ["Beachfront dining", "Spa", "Sunset side"], "productTags": ["Sunset side"], "hours": "Resort restaurant and beach service through the day into dinner", "why": "Gold sits on Kendwa beach, which travel listings describe as non-tidal: the water does not retreat across the flats the way it does on the east coast, so you can swim off the sand at most hours. It has two kitchens. Kilimanjaro, the main room, serves all day with Italian, French, Mauritian and local dishes. Gold, the smaller restaurant, cooks from fresh fish, local spices and Zanzibari ingredients. The beach bar faces west for sunset.", "address": "Kendwa Beach, Kaskazini A, Unguja", "phone": "+255 779 700 005", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.753253, "lng": 39.289958, "category": "houses", "subcat": "THE BEACH HOUSES", "hook": "Five-star villas on Kendwa sand, with two restaurants and a beach bar facing the sunset over Tumbatu.", "signature": "A table on the sand for the last hour of light", "verdict": "Book it for the position and the service; the kitchen is competent resort cooking, not a destination in itself.", "caveat": "Resort pricing, and the beach in front is public. Closed for its annual break 9 May–10 June in 2026.", "price_range": "Upper resort band", "reservation": "Advisable for non-residents", "best_time": "17:00 to sunset", "dishes": [{"name": "Grilled catch of the day", "note": "bought off the northern landings"}, {"name": "Coconut-and-spice curry", "note": "the house Swahili register"}, {"name": "Sundowner on the sand", "note": "the actual reason to come at this hour"}]},
    {"id": "essque-zalu", "cat": "shop", "tier": "several", "priority": 7, "name": "Essque Zalu Zanzibar — The Jetty", "short": "Essque Zalu", "neighborhood": "Nungwi · east side, away from the strip", "maps": "https://www.google.com/maps/search/?api=1&query=Essque+Zalu+Zanzibar+Nungwi", "badge": "JETTY", "tags": ["Jetty restaurant", "East side", "Quiet end"], "productTags": [], "hours": "Resort dining; The Jetty over the water", "why": "Essque Zalu is in a natural cove on the northeast side of the cape, facing away from Nungwi's west-beach bars. The resort's seafood restaurant is at the far end of its long jetty, so you eat over open water with the shore behind you. It serves light lunches and fuller dinners built around fresh fish. Since March 2026 the Jetty has closed Monday to Wednesday in low season, so check the day before you go.", "address": "Nungwi, Kaskazini A, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.724355, "lng": 39.307051, "category": "houses", "subcat": "THE BEACH HOUSES", "hook": "A seafood restaurant at the end of a long jetty, in a cove on the quiet northeast side of the Nungwi cape.", "verdict": "Come for the position and the silence; the food is competent resort cooking and the jetty is the event.", "caveat": "The east side loses the sunset — a lunch and moonlight address. The Jetty closes Monday to Wednesday in low season (2026 notice).", "price_range": "Upper resort band", "reservation": "Recommended", "best_time": "Lunch, or dinner on a bright moon", "dishes": [{"name": "Seafood on the jetty", "note": "the whole reason; the water is directly beneath you"}, {"name": "Long lunch out of the wind", "note": "the east side is sheltered when the kusi is up"}], "charter": {"price": "Upper resort band", "book": "Recommended; The Jetty closes Monday to Wednesday in low season (2026)", "dress": "Smart resort", "warn": "The east side: no sunset — come for lunch or moonlight", "fit": "A dining room on stilts over the water, on the quiet side of the cape."}},
    {"id": "mkokotoni", "cat": "market", "tier": "several", "priority": 36, "name": "Mkokotoni landing & market", "short": "Mkokotoni", "neighborhood": "West coast · the district capital, ~20 km south of Kendwa", "maps": "https://www.google.com/maps/search/?api=1&query=Mkokotoni+Zanzibar", "badge": "MARKET", "tags": ["Regional capital of Unguja North", "Morning auction", "Cash, TZS"], "productTags": ["Fish landing", "Cash"], "hours": "Auctions from early morning; the market runs through the morning", "why": "Mkokotoni is the north-west coast town where boats bring their catch ashore and local buyers, men and women, haggle over it on the spot, a market for people who live here rather than a sight laid on for visitors. It faces Tumbatu across a narrow channel, and the island's largest old mosque ruin stands on the shore looking back at it. Go early and bring Tanzanian shillings in small notes.", "address": "Mkokotoni, Kaskazini A, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.874865, "lng": 39.255888, "category": "landings", "subcat": "WHERE THE BOATS LAND", "hook": "The fish landing at Mkokotoni, on Unguja's north-west coast, directly across the water from Tumbatu.", "signature": "The first auction of the morning, before the town buyers clear the slab", "verdict": "If you cook, this is the most useful hour on the island: it is where the north's fish is actually priced.", "caveat": "Arrive before mid-morning or the good fish is gone. Cash only. This is a working market, not a tour stop.", "price_range": "Wholesale — bring shillings and small notes", "reservation": "None", "best_time": "First light to about 09:00", "dishes": [{"name": "Nguru (kingfish)", "note": "the coast's standard fish — buy it whole and have it butterflied"}, {"name": "Jodari (tuna)", "note": "landed here more often than at Nungwi; the price gap is the reason to drive"}, {"name": "Pweza (octopus)", "note": "cheapest around the spring tides, when the reef-flat gathering is good"}, {"name": "Dagaa", "note": "the small dried fish, sold by the scoop — the island's own store-cupboard protein"}], "hot_this_month": "Spring tides around 26 Oct and 24 Nov — the biggest landings of each month."},
    {"id": "darajani", "cat": "market", "tier": "several", "priority": 44, "name": "Darajani Market", "short": "Darajani", "neighborhood": "Stone Town · Market Street", "maps": "https://www.google.com/maps/search/?api=1&query=Darajani+Market+Zanzibar", "badge": "MARKET", "tags": ["From dawn", "Fish hall at the back", "Cash"], "productTags": ["Spice", "Cash"], "hours": "From dawn; the fish hall is finished by late morning", "why": "The tin-roofed hall on Market Street was opened in August 1904 for Sultan Ali bin Hamud, designed by the British architect J.H. Sinclair, and Stone Town still calls it Marikiti Kuu, the main market. It sells what households need: cloves, cardamom and cinnamon loose by weight, rice and grain, fruit, meat, and the morning's fish in a hall you find by its smell. Buy spice here by the scoop rather than boxed for the airport.", "address": "Market Street, Darajani, Stone Town", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -6.162211, "lng": 39.193731, "category": "landings", "subcat": "WHERE THE BOATS LAND", "hook": "Stone Town's main food market since 1904: spice by the scoop, fish on slabs, fruit and grain.", "signature": "Cloves bought loose by weight, and a cup of kahawa chungu at the market edge", "verdict": "The best provisioning stop on Unguja and the only place to buy spice at a real price.", "caveat": "Crowded, hot, and the fish hall is not for the squeamish. Buy spice loose by weight, never in a printed gift box — the box costs more than the cloves.", "price_range": "Market prices, TZS, cash", "reservation": "None", "best_time": "07:00–10:00", "dishes": [{"name": "Cloves (karafuu)", "note": "the island's whole history, sold by the scoop"}, {"name": "Cardamom, cinnamon, nutmeg", "note": "buy loose; smell before you pay"}, {"name": "Kahawa chungu", "note": "bitter coffee from a brass kettle on charcoal"}]},
    {"id": "kizimbani", "cat": "market", "tier": "several", "priority": 47, "name": "Kizimbani spice plantation", "short": "Kizimbani", "neighborhood": "Central Unguja · inland from Stone Town, on the Kendwa road", "maps": "https://www.google.com/maps/search/?api=1&query=Kizimbani+Zanzibar+spice+farm", "badge": "SPICE", "tags": ["Half day", "Clove, nutmeg, vanilla, cinnamon", "Dry-season harvest"], "productTags": ["Spice"], "hours": "Daytime tours, roughly half a day including transfer", "why": "The clove is an unopened flower bud, and at Kizimbani you see it on the tree before it is dried and sold by the scoop in Stone Town. The guided walk goes plant by plant: nutmeg split to show the red mace around the seed, vanilla vine, cinnamon bark and leaf, lemongrass, pepper, with fruit to taste on the way. The dry months from June to October are the best time to go.", "address": "Kizimbani, central Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "category": "landings", "subcat": "WHERE THE BOATS LAND", "hook": "A spice farm in central Unguja where you see cloves, nutmeg, vanilla and cinnamon on the plant.", "signature": "A clove picked green off the tree and rolled between your fingers", "verdict": "The right spice farm if you actually cook — you leave knowing what an unopened flower bud smells like, which no jar will teach you.", "caveat": "Every driver has a spice farm they are paid to take you to. Name Kizimbani and hold to it. Harvest activity peaks in the dry seasons — June to October and December to February.", "price_range": "Half-day tour with transfer", "reservation": "Arrange the day before", "best_time": "Morning, dry season", "dishes": [{"name": "Clove (karafuu)", "note": "the unopened flower bud — the island's whole economy"}, {"name": "Nutmeg and mace", "note": "one fruit, two spices — the demonstration is worth the trip"}, {"name": "Vanilla", "note": "the vine, hand-pollinated"}, {"name": "Cinnamon bark and leaf", "note": "the leaf smells of clove; that surprise is the lesson"}], "hot_this_month": "The last weeks of the mwaka clove harvest (July to November): picking and drying still to see."},
    {"id": "combo-1990", "cat": "shop", "tier": "plenty", "priority": 55, "name": "Combo 1990", "short": "Combo 1990", "neighborhood": "Nungwi · the middle of the village, off the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Combo+1990+Nungwi+Zanzibar", "badge": "TAPAS", "tags": ["Seven tables", "Closed Mondays", "Swahili tapas"], "productTags": ["Swahili", "Halal", "Cash"], "hours": "12:00–23:00, closed Mondays (Aug 2026); one listing gives 11:00–23:00 daily — check", "why": "Combo 1990 sits in the middle of Nungwi village rather than on the beach, and its format is the lesson: a spread of small plates from the day's pots, so you taste several Swahili dishes in one sitting rather than committing to one. A French writer on Nungwi singled it out for exactly this, noting the plates cost a few euros. Ugali, rice and chapati come alongside.", "address": "Nungwi village, Kaskazini A, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "category": "swahili", "subcat": "THE SWAHILI KITCHENS", "hook": "A small Nungwi village restaurant serving Swahili dishes as a spread of small plates.", "person": "Joy — named in review after review before the food is", "signature": "The Swahili tapas — five local dishes, rice or ugali, chapati", "verdict": "The fastest education in this island's cooking that money can buy, and it costs almost nothing.", "caveat": "Cash. No alcohol — a village kitchen in a Muslim village. Dress covered walking here. Check whether it is open on a Monday.", "price_range": "Low — village pricing", "reservation": "None — turn up", "best_time": "Early evening, before the pots run down", "dishes": [{"name": "Swahili tapas (five dishes)", "note": "the order; a vegetarian version exists"}, {"name": "Ugali", "note": "the stiff maize staple — ask for it instead of rice once"}, {"name": "Chapati", "note": "laminated, torn, used as the cutlery"}, {"name": "Coconut curry", "note": "whatever is in the pot that day"}]},
    {"id": "machnoo", "cat": "shop", "tier": "plenty", "priority": 13, "name": "Machnoo Local Restaurant", "short": "Machnoo", "neighborhood": "Nungwi · near the Sharp football ground, off the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Machnoo+Restaurant+Nungwi+Zanzibar", "badge": "SWAHILI", "tags": ["Mon–Sat 11:00–22:30", "Sun from 07:00", "Sandy floor"], "productTags": ["Swahili", "Halal", "Cash"], "hours": "Mon–Sat 11:00–22:30 · Sun 07:00–22:30", "why": "Machnoo is in Nungwi village by the Sharp football ground, a few streets back from the beach, and is one of the few places here that opens for breakfast on a Sunday, at 07:00. The menu is village food: octopus in coconut curry, crisp coconut-crusted fish, chicken pilau, chicken chapati wraps and beef samosas, with more vegetarian dishes than most local kitchens. Bring Tanzanian shillings, as most people pay in cash.", "address": "Near the Sharp football ground, Nungwi village, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "category": "swahili", "subcat": "THE SWAHILI KITCHENS", "hook": "A village kitchen by the Sharp football ground in Nungwi, serving octopus curry and pilau for shillings.", "signature": "Octopus in coconut curry, or the crisp coconut fish", "verdict": "The most generous plate-for-price on the north tip, and open on a Sunday morning when little else is.", "caveat": "Cash. No alcohol — a village kitchen in a Muslim village. Dress covered walking here. ⚠ Not the same place as Combo 1990: the seven-table Swahili-tapas room is that one, a few streets away.", "price_range": "Low — village pricing", "reservation": "None", "best_time": "Sunday morning, or any evening", "dishes": [{"name": "Pweza wa nazi", "note": "octopus in coconut curry — the order"}, {"name": "Crisp coconut fish", "note": "the other one worth crossing the village for"}, {"name": "Chicken pilau", "note": "spice cooked into the rice"}, {"name": "Beef samosa", "note": "the snack while you wait"}, {"name": "Veggie and falafel wraps", "note": "a real vegan option, which is rare here"}], "charter": {"price": "Low — village pricing", "book": "No bookings — turn up", "dress": "Covered shoulders and knees: this is the village, not the beach", "warn": "Cash only · no alcohol · Mon–Sat from 11:00, Sun from 07:00 (Aug 2026)", "fit": "Octopus in coconut curry at the price the village pays, on a sandy floor."}},
    {"id": "lukmaan", "cat": "shop", "tier": "plenty", "priority": 43, "name": "Lukmaan Restaurant", "short": "Lukmaan", "neighborhood": "Stone Town · New Mkunazini Road", "maps": "https://www.google.com/maps/search/?api=1&query=Lukmaan+Restaurant+Stone+Town+Zanzibar", "badge": "SWAHILI", "tags": ["Point-at-the-pots", "Cheap", "Where the town eats"], "productTags": ["Swahili", "Halal", "Cash"], "hours": "Through the day from breakfast", "why": "There is no menu at Lukmaan. You go to the counter, look at what is in the trays that day, and point: biryani, pilau, fried fish, coconut curries, cassava, spinach, fresh naan. Plates come out large and cheap, eaten at shared tables among people who live in Stone Town rather than visit it. It sits on Mkunazini Street a few minutes' walk from Christ Church, which makes it the obvious lunch after the slave-market memorial.", "address": "New Mkunazini Road, Stone Town", "phone": "+255 745 996 317", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -6.163419, "lng": 39.191637, "category": "swahili", "subcat": "THE SWAHILI KITCHENS", "hook": "A Stone Town canteen near the old slave market: point at the trays on the counter, and they plate it up.", "signature": "A tray of four or five things chosen at the counter, with urojo alongside", "verdict": "The single most educational plate on the island, and it costs almost nothing.", "caveat": "No alcohol, shared tables, and it empties fast at Friday lunch. Cash.", "price_range": "Low", "reservation": "None", "best_time": "Lunch", "dishes": [{"name": "Biryani", "note": "the Indian Ocean's layered rice, done properly"}, {"name": "Urojo", "note": "the mango-and-tamarind soup, built at the counter"}, {"name": "Fish in coconut", "note": "mchuzi wa samaki — the base register of this island"}, {"name": "Mkate wa kumimina", "note": "the poured rice bread, when it is on"}], "web": "https://lukmaanrestaurant.shop/"},
    {"id": "mama-mia-nungwi", "cat": "shop", "tier": "plenty", "priority": 11, "name": "Mama Mia", "short": "Mama Mia", "neighborhood": "Nungwi · on the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Mama+Mia+Nungwi+Zanzibar", "badge": "GELATO", "tags": ["Italian gelato", "Brick-oven pizza", "On the beach"], "productTags": ["Italian", "Gelato"], "hours": "Through the day into the evening", "why": "Mama Mia is an Italian restaurant on Nungwi beach. The thing reviewers mention most is the gelato, which one compared favourably with the Venchi chain; the pizzas come from a brick oven. The menu also covers lobster, pasta, octopus salad and a homemade tiramisu. It faces the water, so a cone at sunset is the obvious order. Reviewers say it is pricey by Zanzibar standards, which suits a treat more than a nightly dinner.", "address": "Nungwi, Kaskazini A, Unguja", "phone": "+255 773 360 584", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.728092, "lng": 39.291556, "category": "italian", "subcat": "THE ITALIAN COAST", "hook": "A beachfront Italian on Nungwi sand known for its gelato and brick-oven pizza.", "signature": "A cone of gelato walked down the beach at sunset", "verdict": "The Italian room on Nungwi sand: pizza from the brick oven and a gelato cabinet at the end of the day.", "caveat": "Flavours run out late in the day; go before the evening rush if you want the full cabinet.", "price_range": "Mid to upper — reviewers call it expensive for Zanzibar (Oct 2026)", "reservation": "None", "best_time": "Late afternoon", "dishes": [{"name": "Italian gelato"}, {"name": "Brick-oven pizza"}, {"name": "Homemade tiramisu"}], "web": "https://www.mamamiarestaurantzanzibar.com/"},
    {"id": "bistro-del-mar", "cat": "shop", "tier": "plenty", "priority": 9, "name": "Bistro' del M@r", "short": "Bistro del Mar", "neighborhood": "Kendwa · Kendwa Road, behind the sand", "maps": "https://www.google.com/maps/search/?api=1&query=Bistro+del+Mar+Kendwa+Zanzibar", "badge": "ITALIAN", "tags": ["Italian-owned", "Wood-fired pizza", "Road side"], "productTags": ["Italian", "Wood-fire"], "hours": "Lunch and dinner; road-side, not on the sand", "why": "Bistro del M@r is the restaurant inside Kendwa Garden's, a small B&B in Kendwa, and serves Italian food from breakfast through dinner, with tables in the garden or facing the sea. Kendwa has a sizeable Italian visitor trade, and kitchens like this one cook for it at guesthouse prices, a step below the beach resorts. We could not confirm it is trading this season, so call ahead.", "address": "Kendwa Road, Kendwa, Kaskazini A", "phone": "+255 777 108 466", "status": "unverified", "statusChecked": "", "lat": -5.752714, "lng": 39.290405, "category": "italian", "subcat": "THE ITALIAN COAST", "hook": "The Italian restaurant at Kendwa Garden's B&B, open from breakfast through dinner.", "signature": "A wood-fired pizza and a plate of seafood pasta, off the sand and out of the wind", "verdict": "The best-value proper Italian cooking in Kendwa, and the correct answer to a fourth consecutive night of grilled fish.", "caveat": "On the road, not the beach — no view, and that is the trade you are making.", "price_range": "Mid — well below the beach-front rate", "reservation": "Walk in; call at weekends", "best_time": "Dinner", "dishes": [{"name": "Wood-fired pizza", "note": "the oven is the point"}, {"name": "Seafood pasta", "note": "island fish, Italian technique"}, {"name": "Espresso", "note": "the one place here that treats it as a discipline"}], "charter": {"price": "Mid — below beach-front rates", "book": "Call at weekends, otherwise walk in", "dress": "Anything", "warn": "The Kendwa road is unlit walking back — take a torch", "fit": "Wood-fired pizza and proper pasta when the fourth grilled fish is one too many."}},
    {"id": "hanoi-house", "cat": "shop", "tier": "plenty", "priority": 64, "name": "Hanoi House Nungwi", "short": "Hanoi House", "neighborhood": "Nungwi · main road", "maps": "https://www.google.com/maps/search/?api=1&query=Hanoi+House+Nungwi+Zanzibar", "badge": "VIETNAM", "tags": ["11:00–23:00", "24-hour pho broth", "Phin coffee"], "productTags": [], "hours": "11:00–23:00", "why": "Hanoi House began as a Vietnamese cafe in Paje on the east coast in 2021, and the Nungwi branch was its first franchise, followed by one in a 1950s building in Stone Town. The pho broth simmers for twenty-four hours with five-spice before it meets flat rice noodles and herbs. Reviewers come back for the dumplings, bao, homemade sodas and coconut coffee.", "address": "Main road, Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "category": "italian", "subcat": "THE OTHER KITCHENS", "hook": "A Vietnamese kitchen on Nungwi's main road: 24-hour pho broth, dumplings, phin coffee.", "signature": "Phở with the long broth, and a phin coffee after", "verdict": "The best non-Swahili, non-Italian cooking on the north tip, by a distance.", "caveat": "A franchise of the Paje café (opened 2021): judge it on the broth, which holds up. Pork is on the menu.", "price_range": "Mid", "reservation": "None", "best_time": "Lunch or dinner", "dishes": [{"name": "Phở", "note": "twenty-four-hour broth — the test, and it passes"}, {"name": "Bún chả", "note": "grilled pork, noodles, herbs"}, {"name": "Hand-folded dumplings", "note": "made on site"}, {"name": "Phin coffee", "note": "dripped at the table, Vietnamese-style"}]},
    {"id": "jf-kili", "cat": "shop", "tier": "plenty", "priority": 57, "name": "JF Kili Coffee House", "short": "JF Kili", "neighborhood": "Nungwi · main road opposite Hanoi House, plus a truck by the square", "maps": "https://www.google.com/maps/search/?api=1&query=JF+Kili+Coffee+House+Nungwi+Zanzibar", "badge": "COFFEE", "tags": ["Own farm under Kilimanjaro", "Two sites", "08:00–21:00"], "productTags": ["Swahili", "Cash"], "hours": "08:00–21:00", "why": "The owners are Tanzanian and grow the coffee themselves on a farm under Kilimanjaro, then sell it at the other end of the country on a beach where most coffee arrives in a tin. There are two places to drink it in Nungwi: the coffee house on the main road opposite Hanoi House, and a truck with a few tables on the big square next to MJ's. Waffles and cakes as well.", "address": "Main road, Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "category": "breakfast", "subcat": "THE BREAKFAST TABLES", "hook": "A Nungwi coffee house and coffee truck pouring beans from the owners' farm below Kilimanjaro.", "person": "Locally founded and locally run", "signature": "A flat white from Kilimanjaro-grown beans, at the truck by the square", "verdict": "The only serious coffee on the north tip, and the only one that is Tanzanian all the way back to the tree.", "caveat": "Two locations and they are not the same room — the truck is the more charming of the pair.", "price_range": "Low", "reservation": "None", "best_time": "Breakfast, or the truck at dusk", "dishes": [{"name": "Kilimanjaro-grown coffee", "note": "the farm is the story"}, {"name": "Waffles", "note": "the breakfast order"}, {"name": "Cakes", "note": "the mid-afternoon one"}]},
    {"id": "passion-thyme", "cat": "shop", "tier": "plenty", "priority": 59, "name": "Passion &amp; Thyme", "short": "Passion & Thyme", "neighborhood": "Nungwi · next to Nungwi House, off the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Passion+and+Thyme+Nungwi+Zanzibar", "badge": "BAKERY", "tags": ["French bakery", "Deli", "Breakfast to dinner"], "productTags": [], "hours": "Breakfast through dinner", "why": "Passion & Thyme is a French-run cafe and bakery set back from the beach, next to Nungwi House, that bakes its own bread and pastries and lets you build your own salad. It also runs as a deli for Zanzibari and Tanzanian food products, makes kombucha and plant milks, and takes orders for cakes. Vegan and gluten-free options are on the menu, which is rare on this strip.", "address": "Nungwi, Kaskazini A", "phone": "—", "status": "unverified", "statusChecked": "", "lat": -5.729606, "lng": 39.293172, "category": "breakfast", "subcat": "THE BREAKFAST TABLES", "hook": "A French cafe, bakery and deli in Nungwi village: bread, quiche, build-your-own salad, juices.", "verdict": "The bread is the reason: a French bakery and deli on a coast with very little of either.", "caveat": "Off the beach, next to Nungwi House.", "price_range": "Mid", "reservation": "None", "best_time": "Lunch", "dishes": [{"name": "Bread and pastries"}, {"name": "Breakfast"}, {"name": "Deli plates"}]},
    {"id": "mahi-mahi", "cat": "shop", "tier": "plenty", "priority": 58, "name": "Mahi Mahi", "short": "Mahi Mahi", "neighborhood": "Nungwi · the quiet north end of the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Mahi+Mahi+Restaurant+Nungwi+Zanzibar", "badge": "BEACH", "tags": ["07:30–23:30", "Feet in the sand", "Small menu"], "productTags": ["Sunset side"], "hours": "07:30–23:30", "why": "Mahi Mahi keeps a short menu of fresh seafood and international plates at the quiet north end of Nungwi beach, and its listed hours start at half past seven, so breakfast happens on the sand rather than in a hotel dining room. Reviewers single out the fish curry, babaganoush and hummus. There are sunbeds and shisha, and kite-surfing lessons run off the beach in front.", "address": "North Nungwi beach, Kaskazini A", "phone": "—", "status": "unverified", "statusChecked": "", "category": "breakfast", "subcat": "THE BREAKFAST TABLES", "hook": "A small beach bar and restaurant on the quiet northern stretch of Nungwi sand, serving from 07:30.", "signature": "Breakfast at 08:00 before the beach fills", "verdict": "The best early table on Nungwi sand, and the small menu is the reason.", "caveat": "Quiet end means a walk from the bar strip.", "price_range": "Mid", "reservation": "None", "best_time": "07:30–09:30, or sunset", "dishes": [{"name": "Breakfast on the sand", "note": "from 07:30 — earlier than anything else out here"}, {"name": "Fresh seafood", "note": "the short, sensible menu"}, {"name": "Smoothies", "note": "the daytime order"}]},
    {"id": "baraka-beach-rest", "cat": "shop", "tier": "plenty", "priority": 15, "name": "Baraka Beach Restaurant", "short": "Baraka Beach", "neighborhood": "Nungwi · on the sand", "maps": "https://www.google.com/maps/search/?api=1&query=Baraka+Beach+Restaurant+Nungwi", "badge": "SEAFOOD", "tags": ["On the sand", "Seafood", "Bungalows attached"], "productTags": ["Swahili"], "hours": "Through the day into dinner", "why": "Baraka is the beach restaurant of a 17-room bungalow hotel on Nungwi sand, and it works the way the better beach grills here do: in the evening the day's catch is laid out on a table beside the grill, you choose a fish or a lobster, and it is cooked for you. It is plain and good value, and the table is on the beach itself.", "address": "Nungwi, Kaskazini A, Unguja", "phone": "+255 623 026 767", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.728026, "lng": 39.293574, "category": "grills", "subcat": "THE FIRE", "hook": "Seafood on Nungwi sand in front of a 17-room bungalow hotel, with the day's catch laid out by the grill.", "verdict": "Fine, cheap, and exactly where you want to be at two in the afternoon.", "caveat": "Beach-front variability: it is better when it is busy.", "price_range": "Low-mid", "reservation": "None", "best_time": "Lunch", "dishes": [{"name": "Grilled catch", "note": "off the morning landing"}, {"name": "Coconut rice", "note": "wali wa nazi — the standard side"}], "web": "https://barakabeachrestaurant.net/"},
    {"id": "smiles-beach", "cat": "shop", "tier": "plenty", "priority": 52, "name": "Smiles Beach Hotel", "short": "Smiles", "neighborhood": "Nungwi · Mkunguni side", "maps": "https://www.google.com/maps/search/?api=1&query=Smiles+Beach+Hotel+Nungwi", "badge": "HOTEL", "tags": ["Small hotel", "Restaurant open to non-residents"], "productTags": [], "hours": "Breakfast through dinner", "why": "Smiles is a small hotel of 22 rooms, each with a balcony or patio, a few steps from Nungwi beach and close to the Mnarani turtle aquarium, with a pool, a spa and its own restaurant. The booking listings note it closes for the whole of April. Ring ahead to ask whether the kitchen will seat non-residents, since that is not stated anywhere current.", "address": "Nungwi, Kaskazini A", "phone": "+255 773 444 105", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.724909, "lng": 39.294185, "category": "grills", "subcat": "THE FIRE", "hook": "A 22-room hotel a few steps from Nungwi beach, with a restaurant; it shuts for April.", "verdict": "A calm table when the strip is not.", "caveat": "Limited menu out of season.", "price_range": "Low-mid", "reservation": "None", "best_time": "Dinner", "dishes": [{"name": "Grilled catch of the day", "note": "off the Nungwi landing that morning"}, {"name": "Mishkaki", "note": "marinated skewers over charcoal"}, {"name": "Coconut rice", "note": "wali wa nazi, the standard side to anything off the fire"}]},
    {"id": "makofi", "cat": "shop", "tier": "plenty", "priority": 60, "name": "Makofi Guest House", "short": "Makofi", "neighborhood": "Nungwi · off the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Makofi+Guest+House+Nungwi+Zanzibar", "badge": "BBQ", "tags": ["Weekly BBQ night", "Roman pizza", "Guest house"], "productTags": ["Wood-fire", "Cash"], "hours": "BBQ night weekly; Pizza Gourmet by Makofi the rest of the week", "why": "Makofi is a guest house about a minute's walk from Nungwi beach whose kitchen does two jobs. Its restaurant, Pizza Gourmet By Makofi, makes Roman-style scrocchiarella, the thin, crisp pizza of Rome rather than the soft Neapolitan kind. Once a week it lays on a BBQ buffet with a fire show, at US$25 a head, US$20 for vegetarians and children, with limited places that must be reserved.", "address": "Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.731185, "lng": 39.292706, "category": "grills", "subcat": "THE FIRE", "hook": "A Nungwi guest house with a weekly BBQ buffet and fire show, and crisp Roman pizza the other nights.", "signature": "The weekly BBQ night", "verdict": "The best-value set-piece evening in Nungwi.", "caveat": "BBQ night is weekly and the night can move: ask which one the day you arrive, and book it.", "price_range": "BBQ US$25 adults, US$20 children and vegetarians (seen Oct 2026)", "reservation": "Essential for BBQ night", "best_time": "BBQ night; otherwise any evening for pizza", "dishes": [{"name": "The BBQ night"}, {"name": "Roman scrocchiarella pizza"}]},
    {"id": "che-rock", "cat": "shop", "tier": "plenty", "priority": 62, "name": "CHE Rock Bar &amp; Restaurant", "short": "Che Rock", "neighborhood": "Nungwi · main entrance to the beach, beside Pasha Nungwi", "maps": "https://www.google.com/maps/search/?api=1&query=CHE+Rock+Bar+Nungwi+Zanzibar", "badge": "ROCK", "tags": ["Tacos and burgers", "Cocktails", "Beach entrance"], "productTags": ["Cash"], "hours": "Daily 12:00–23:00 (Aug 2026); one listing gives 16:30–00:00 — call ahead", "why": "CHE calls itself Zanzibar's first and only rock bar, and it sits at the main entrance to Nungwi beach next to the Pasha Nungwi hotel. The playlist is rock rather than the Afro house heard elsewhere on the strip. The kitchen does tacos, burgers and pub classics with some fresh seafood, the bar pours local and imported spirits, and there is karaoke and football on the screens.", "address": "Main entrance to Nungwi Beach, beside Pasha Nungwi Hotel", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.731057, "lng": 39.292431, "category": "chefs-eat", "subcat": "WHERE THE INSTRUCTORS EAT", "hook": "A rock-music bar at the main entrance to Nungwi beach, beside Pasha Nungwi, with tacos and burgers.", "signature": "A burger and a cocktail late in the evening", "verdict": "The most honest room in Nungwi — no sunset markup, no theatre, and the right crowd.", "caveat": "Closes at 23:00. This is not a late-night venue despite the atmosphere.", "price_range": "Low-mid", "reservation": "None", "best_time": "From 21:00", "dishes": [{"name": "Burgers", "note": "the order"}, {"name": "Tacos", "note": "the other order"}, {"name": "Cocktails", "note": "local and imported spirits, full list"}]},
    {"id": "fisherman-local", "cat": "shop", "tier": "plenty", "priority": 17, "name": "The Fisherman Local Restaurant", "short": "Fisherman Local", "neighborhood": "Kendwa · off the road, behind the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Fisherman+Local+Restaurant+Kendwa+Zanzibar", "badge": "LOCAL", "tags": ["Lobster and octopus", "Low prices", "Off the sand"], "productTags": ["Swahili", "Cash"], "hours": "Lunch and dinner", "why": "Fisherman Local is a plain room on the road behind Eden Villa Resort, set back from Kendwa's beach bars, and it cooks seafood at local prices. Reviewers keep coming back to the octopus, which they describe as properly tender, and to the grilled lobster, Indian-style prawn masala, tuna salad and the kitchen's own chilli sauce. It is not on the sand, which is a large part of why the prices are lower.", "address": "Kendwa, Kaskazini A, Unguja", "phone": "+255 777 871 130", "status": "unverified", "statusChecked": "", "lat": -5.754377, "lng": 39.291001, "category": "chefs-eat", "subcat": "WHERE THE INSTRUCTORS EAT", "hook": "A local seafood kitchen on the road behind Eden Villa in Kendwa: grilled lobster, octopus and prawn masala.", "signature": "Grilled lobster or a whole octopus, at roughly half the beach-front rate", "verdict": "The best price-to-plate ratio in Kendwa, full stop.", "caveat": "Cash, no view, and the kitchen runs out. Go early.", "price_range": "Low", "reservation": "None", "best_time": "Early evening", "dishes": [{"name": "Grilled lobster", "note": "the order, and the price is the story"}, {"name": "Pweza wa nazi", "note": "octopus in coconut curry"}, {"name": "Whole grilled fish", "note": "whatever landed"}]},
    {"id": "highland", "cat": "shop", "tier": "plenty", "priority": 63, "name": "Highland Bungalows", "short": "Highland", "neighborhood": "Nungwi · inland, the local end", "maps": "https://www.google.com/maps/search/?api=1&query=Highland+Bungalows+Nungwi+Zanzibar", "badge": "LOCAL", "tags": ["Pool tables", "Football on", "Cheap"], "productTags": ["Cash"], "hours": "Into the night", "why": "Highland Bungalows is a small guest house a short walk back from Nungwi beach, built around a garden and a swimming pool, with an open-plan bar that has a pool table and flat screens showing international football. It is a place to play a frame and watch a match away from the sand. Guests who stay mention the breakfast and the cocktails.", "address": "Nungwi, Kaskazini A", "phone": "—", "status": "unverified", "statusChecked": "", "category": "chefs-eat", "subcat": "WHERE THE INSTRUCTORS EAT", "hook": "A guest-house bar a short walk inland from Nungwi beach, with a pool table and football on the screens.", "verdict": "Good company at a fraction of the beach price, and the last room awake.", "caveat": "A guest house with a pool as well as a bar; basic. Inland and unlit — walk back with someone.", "price_range": "Low", "reservation": "None", "best_time": "Late", "dishes": [{"name": "Chapati wraps", "note": "the late plate"}, {"name": "Stir-fried noodles", "note": "the other one"}]},
    {"id": "sunset-kendwa", "cat": "shop", "tier": "plenty", "priority": 22, "name": "Sunset Kendwa", "short": "Sunset Kendwa", "neighborhood": "Kendwa · next along the sand from Kendwa Rocks", "maps": "https://www.google.com/maps/search/?api=1&query=Sunset+Kendwa+Zanzibar", "badge": "SUNSET", "tags": ["Beach bar", "Casual kitchen", "West-facing"], "productTags": ["Sunset side"], "hours": "Day into evening", "why": "A plain beach lodge of about fifty rooms, with a bar on the sand and a restaurant named for the reason it is here: the beach faces west, so the sun goes down straight in front of it. It sits next along the sand from Kendwa Rocks, so on a Full Moon Saturday it is the nearby place to sit with a drink and watch the sun set. Booking listings say it closes over Christmas and New Year.", "address": "Kendwa Road, Kendwa Beach, Kaskazini A", "phone": "—", "status": "unverified", "statusChecked": "", "lat": -5.751295, "lng": 39.288035, "category": "beach-rooms", "subcat": "THE SAND BARS", "hook": "A Kendwa beach lodge with a sand-side bar and restaurant, next along the beach from Kendwa Rocks.", "verdict": "The sane alternative fifty metres up the beach on a loud night.", "caveat": "Casual kitchen; manage expectations and order simply.", "price_range": "Low-mid", "reservation": "None", "best_time": "16:30 to dark", "dishes": [{"name": "Grilled fish", "note": "the simple order that works"}, {"name": "Sundowner", "note": "the whole point of the address"}]},
    {"id": "z-rooftop", "cat": "shop", "tier": "plenty", "priority": 70, "name": "The Z Hotel rooftop bar", "short": "Z rooftop", "neighborhood": "Nungwi · on top of The Z Hotel", "maps": "https://www.google.com/maps/search/?api=1&query=The+Z+Hotel+Nungwi+Zanzibar", "badge": "ROOFTOP", "tags": ["Happy hour 17:00–20:00", "US$15 minimum", "Arrive early"], "productTags": ["Rooftop", "Sunset side"], "hours": "Afternoon into evening · happy hour 17:00–20:00", "why": "The rooftop of the Z Hotel looks straight west over the channel from the Nungwi beachfront, and it is small, which is why reviewers in early 2026 still tell people to arrive early for sunset. Non-residents pay a US$15 per-person minimum at sunset, cocktails are cheaper during happy hour from five to eight, and some evenings a DJ plays electronic music.", "address": "The Z Hotel, Nungwi Beach, Kaskazini A", "phone": "+255 699 109 096", "status": "confirmed", "statusChecked": "2026-08-22", "category": "beach-rooms", "subcat": "THE SAND BARS", "hook": "The Z Hotel's west-facing rooftop bar in Nungwi: happy hour 17:00-20:00, US$15 sunset minimum.", "signature": "Happy hour from 17:00, facing west", "verdict": "Worth the minimum spend once. Get there early — the good seats go long before the sun does.", "caveat": "⚠ US$15 per person minimum for non-residents at sunset, and a 2% fee on cards (reviews, 2026). Arrive well before sunset or you will be standing.", "price_range": "US$15 minimum spend per non-resident (2026)", "reservation": "Not taken — arrive early", "best_time": "16:30 to hold a seat for 18:30", "dishes": [{"name": "Happy-hour cocktails", "note": "17:00–20:00"}, {"name": "The view", "note": "which is what the minimum spend is actually for"}]},
    {"id": "kendwa-rocks", "cat": "shop", "tier": "plenty", "priority": 21, "name": "Kendwa Rocks Beach Hotel", "short": "Kendwa Rocks", "neighborhood": "Kendwa · centre of the sand", "maps": "https://www.google.com/maps/search/?api=1&query=Kendwa+Rocks+Zanzibar", "badge": "FULLMOON", "tags": ["Full Moon Party since 1996", "Rocks Lounge Tue/Thu/Sat 22:00", "Beachfront"], "productTags": ["Since 1996", "Sunset side"], "hours": "Beach bar and restaurant through the day · The Rocks Lounge Club Tue, Thu, Sat from 22:00", "why": "The hotel's own story puts the first Full Moon Party in 1996: a few friends and guests, a beach fire, drums and acrobats on a clear night. It is now a ticketed event with gates at 19:00, a main stage until about four and a club afterparty until six, run on a Saturday near each full moon. On the other nights it is a 47-room beach hotel with a bar on the sand and a club three nights a week.", "address": "Kendwa Road, Kendwa Beach, Kaskazini A", "phone": "+255 774 415 475", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.752399, "lng": 39.287868, "category": "story", "subcat": "THE OLD HOUSES", "hook": "The Kendwa beach hotel whose monthly Full Moon Party grew from a beach fire among friends in 1996.", "person": "Founded as a small beach hotel; the party began 1996", "signature": "The Full Moon Party — the Saturday after each full moon by the venue's account; check its calendar", "verdict": "Go for the night it is famous for, or go on any other night for a cheap drink on the best-positioned sand in Kendwa; do not go expecting the cooking to be the point.", "caveat": "On party nights this is a several-thousand-person event with a ticket and a buffet — loud, crowded and nothing like the 1996 story. If that is not what you came for, check the moon before you book the room.", "price_range": "Low-mid for food and drink · entrance around 25,000 TZS on club nights and around 50,000 TZS for the Full Moon Party (obs. 2026-08); taxi from Nungwi about 20,000 TZS each way", "reservation": "Not for the bar; book rooms far ahead for full-moon weekends", "best_time": "Sunset any night · the first Saturday after a full moon for the event", "dishes": [{"name": "Grilled fish and chips off the beach kitchen", "note": "the reliable order"}, {"name": "Full Moon buffet", "note": "Zanzibari, Indian, Arabic, Thai and Indonesian, on party nights only"}, {"name": "A cold Kilimanjaro at sunset", "note": "the actual house speciality"}], "signal_chip": {"label": "Since 1996", "full": "Full Moon Party running since 1996 by the venue's own account; monthly, first Saturday after the full moon", "cosign": "Venue's own site, checked 22 Aug 2026"}, "web": "https://www.kendwarocks.com/full-moon-party", "hot_this_month": "Full moons Mon 26 Oct and Tue 24 Nov: by the venue's rule the parties are Sat 31 Oct and Sat 28 Nov (derived; confirm on its calendar)."},
    {"id": "langi-langi", "cat": "shop", "tier": "plenty", "priority": 16, "name": "Langi Langi Beach Bungalows", "short": "Langi Langi", "neighborhood": "Nungwi · beach village, west side", "maps": "https://www.google.com/maps/search/?api=1&query=Langi+Langi+Beach+Bungalows+Nungwi", "badge": "TERRACE", "tags": ["Marhaba restaurant", "At the water's edge", "Traditional Zanzibari dinner"], "productTags": ["Sunset side", "Swahili"], "hours": "Breakfast through dinner", "why": "Langi Langi is a 32-unit beach hotel on Nungwi's west-facing beach, and its restaurant, Marhaba, is a covered open-air room at the water's edge. Reviewers mention an owner known as Rasta who helps in the kitchen. Beyond the seafood and international dishes, Marhaba is known for a Traditional Zanzibari Dinner, and a separate Marhaba Café serves African coffee. Sunset tables face straight out over the channel.", "address": "Nungwi Beach Village, Kaskazini A", "phone": "+255 773 911 000", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.728838, "lng": 39.291665, "category": "story", "subcat": "THE OLD HOUSES", "hook": "Langi Langi's Marhaba restaurant, a covered terrace at the water's edge on Nungwi's west beach.", "signature": "A seafood dinner at Marhaba as the sun goes into the channel", "verdict": "The most reliable independent kitchen on Nungwi beach, and the best terrace among them.", "caveat": "Popular at sunset — the front tables are gone by 17:30 in high season.", "price_range": "Mid", "reservation": "Worth calling for a sunset table", "best_time": "17:00–19:00", "dishes": [{"name": "Traditional Zanzibari dinner"}, {"name": "Seafood"}, {"name": "Coffee at Marhaba Café"}], "web": "http://www.langilangizanzibar.com/", "charter": {"price": "Mid", "book": "Call for a sunset table", "dress": "Casual", "warn": "Front tables go by 17:30 in season", "fit": "The long-standing independent house, its Marhaba terrace at the water's edge."}},
    {"id": "cholos", "cat": "shop", "tier": "plenty", "priority": 24, "name": "Cholo's Bar", "short": "Cholo's", "neighborhood": "Nungwi · on the sand, driftwood end", "maps": "https://www.google.com/maps/search/?api=1&query=Cholo%27s+Bar+Nungwi+Zanzibar", "badge": "DRIFTWOOD", "tags": ["Long-running", "Live music", "Halved dhows as furniture"], "productTags": ["Dhow yard"], "hours": "Afternoon into late; live music some nights", "why": "Travel writers have described it the same way for years: hammocks slung above the bar, benches made from dhow hulls sawn in half, a bathtub doing duty as a urinal, and a few basic shacks to sleep in. The boats came from the yards a short walk up the same beach, which is the most specific thing about the place. It has no website, and no source confirms it is open this season, so walk past and check first.", "address": "Nungwi Beach, Kaskazini A", "phone": "—", "status": "unverified", "statusChecked": "", "lat": -5.727793, "lng": 39.292058, "category": "story", "subcat": "THE OLD HOUSES", "hook": "A driftwood beach bar in Nungwi with benches cut from halved dhow hulls and hammocks over the bar.", "signature": "A drink in a dhow hull with the light going", "verdict": "The one bar up here with a genuine character rather than a decorated one — and the boats are real boats.", "caveat": "Beach-bar standards throughout; go for the room, not the kitchen.", "price_range": "Low", "reservation": "None", "best_time": "Late afternoon onward", "dishes": [{"name": "Cold beer", "note": "the order"}, {"name": "Konyagi and tonic", "note": "the Tanzanian sugar-cane spirit — try it once"}]},
    {"id": "nungwi-fish-market", "cat": "berth", "tier": "berth_top", "priority": 3, "name": "Nungwi fish market & the evening grills", "short": "Nungwi fish market", "neighborhood": "Nungwi · the working beach, north of the hotel line", "maps": "https://www.google.com/maps/search/?api=1&query=Nungwi+market+Zanzibar", "badge": "LANDING", "tags": ["Cash only, TZS", "Dawn for the auction", "Sunset for the grills"], "productTags": ["Fish landing", "Cash", "Halal"], "hours": "Boats and auction from first light; the charcoal grills fire up from about 18:00 until the fish runs out", "why": "This is where Nungwi's boats come in, beside the fishing pier at the village's working end of the beach, and where the catch is sold before it goes to any kitchen on the strip. The beach restaurants nearby lay the day's fish on a table by the grill, and you point at the one you want. Coming here first shows you what the north tip's menus are built from, and roughly what that fish costs before a hotel adds its margin.", "address": "Nungwi beach, Kaskazini A, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.727879, "lng": 39.293684, "category": "street", "subcat": "THE STREET", "hook": "Nungwi's working fish landing by the pier, where the night's catch comes ashore and is sold off the sand.", "person": "The Nungwi boat crews and the grill vendors", "signature": "A whole reef fish, weighed off the ice and grilled to order, with rice and kachumbari", "verdict": "The best value and the truest plate on the north tip — and the one place here where the tourist and the fisherman are eating the same fish at the same fire.", "caveat": "Cash only, no menu, no receipt, and prices are negotiated: settle the price per kilogram before the fish is put on the coals or you will pay a stranger's rate. Hygiene is a working beach's hygiene — go when it is busy and the turnover is fast.", "price_range": "A few thousand TZS a head to eat well — the cheapest good meal on this coast", "reservation": "None — turn up", "best_time": "06:00–08:00 for the landing and the auction · from 18:00 for the grills", "dishes": [{"name": "Whole grilled kingfish (nguru)", "note": "the north tip's standard fish; ask for it butterflied"}, {"name": "Pweza wa kuchoma", "note": "grilled octopus — tenderised, charred, lime"}, {"name": "Grilled squid (ngisi)", "note": "fast over the coals; overcooked is the local failure mode"}, {"name": "Kachumbari", "note": "tomato, onion, lime, chilli — the plate's whole acidity"}], "signal_chip": {"label": "The landing", "full": "Working artisanal fish landing and evening grill market, Nungwi village", "cosign": "Confirmed trading 22 Aug 2026"}, "hot_this_month": "Spring tides around the full moons of 26 Oct and 24 Nov: the biggest landings and the most octopus."},
    {"id": "forodhani", "cat": "market", "tier": "plenty", "priority": 40, "name": "Forodhani Gardens night market", "short": "Forodhani", "neighborhood": "Stone Town · the seafront, in front of the Old Fort", "maps": "https://www.google.com/maps/search/?api=1&query=Forodhani+Gardens+Zanzibar", "badge": "NIGHT", "tags": ["From about 18:00", "Cash only", "Agree the price first"], "productTags": ["Aga Khan 2009", "Cash"], "hours": "Stalls from about 18:00 until about 21:00", "why": "The name means customs, after the customs house that stood here, and the gardens were called Jubilee Gardens until the 1964 revolution. The Aga Khan Trust for Culture rebuilt the park, seawall and lighting, finishing in July 2009. Each evening the grills and fryers go up in front of the Old Fort: Zanzibar pizza folded and fried to order, urojo ladled over bhajia and crisps, sugar cane pressed with lime and ginger.", "address": "Mizingani Road, Stone Town", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -6.160596, "lng": 39.188798, "category": "street", "subcat": "THE STREET", "hook": "Stone Town's seafront park, rebuilt in 2009, where food stalls set up every evening at sunset.", "signature": "A Zanzibar pizza cooked to order and a cup of urojo", "verdict": "Go for the things cooked in front of you and nothing else — that rule turns a tourist trap into the best street food on the island.", "caveat": "⚠ Never take from a tray that has been sitting out. Agree the price before it is made — overcharging visitors is routine here. Cash, small notes.", "price_range": "A few thousand TZS", "reservation": "None", "best_time": "18:00–20:00", "dishes": [{"name": "Zanzibar pizza", "note": "fried dough parcel with egg and filling — cooked to order, never pre-made"}, {"name": "Urojo (Zanzibar mix)", "note": "mango-tamarind soup with bhajia, potato and cassava crisps"}, {"name": "Mishkaki", "note": "marinated grilled skewers, straight off the coals"}, {"name": "Sugar-cane juice with lime and ginger", "note": "pressed in front of you; watch the mill is rinsed"}], "hot_this_month": "Nyerere Day, Wed 14 Oct, is a public holiday; the night market runs as usual after sunset."},
    {"id": "nungwi-village", "cat": "market", "tier": "plenty", "priority": 54, "name": "Nungwi village shops & the provisioning line", "short": "Nungwi village shops", "neighborhood": "Nungwi · inland of the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Nungwi+Zanzibar", "badge": "DUKAS", "tags": ["Small dukas", "Cash", "No big supermarket"], "productTags": ["Cash", "Halal"], "hours": "Daylight into early evening; Friday prayers close things around midday", "why": "Cooking at the north tip means buying the way the village does. Small shops through Nungwi sell rice, flour, oil, eggs, onions, tomatoes, limes, chillies and charcoal, with a couple of mini-markets on the square. Fruit comes from street sellers, fish and octopus from the boats at the landing in the morning. Imported wine, cheese and bulk spice mean a trip to Stone Town, a full day there and back.", "address": "Nungwi village, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.727227, "lng": 39.299202, "category": "street", "subcat": "THE STREET", "hook": "Nungwi's small shops and fruit sellers: rice, oil, eggs, limes, charcoal, and fish from the landing.", "verdict": "Perfectly adequate for cooking simply and completely inadequate for cooking Europeanly. Plan accordingly.", "caveat": "⚠ Cold chain is the constraint: buy fish at the landing and cook it the same day. Cash, small notes. Friday around midday the village closes for prayers.", "price_range": "Village prices", "reservation": "None", "best_time": "Morning", "dishes": [{"name": "Mandazi", "note": "lightly sweet fried dough with cardamom — from first light, gone by nine"}, {"name": "Chai ya tangawizi", "note": "tea boiled hard with fresh ginger, from any duka"}, {"name": "Vitumbua", "note": "rice-and-coconut cakes cooked in a dimpled pan, mornings only"}, {"name": "Chipsi mayai", "note": "the chip omelette — the late plate, from the carts"}], "buy": "Rice, flour, oil, eggs, onions, tomatoes, limes, chillies, charcoal, UHT milk, island bananas, mango, papaya, passion fruit — all from the village dukas and fruit sellers.", "galley": "Fish and octopus off the Nungwi landing at dawn, or Mkokotoni for better prices and range. Ice is the bottleneck: buy it where you buy the fish and use it that day. Everything imported is a Stone Town run — budget three hours each way."},
    {"id": "zanzibar-watersports", "cat": "logistics", "tier": "plenty", "priority": 28, "name": "Zanzibar Watersports @ Kendwa Rocks", "short": "Zanzibar Watersports", "neighborhood": "Kendwa · on the beach at Kendwa Rocks", "maps": "https://www.google.com/maps/search/?api=1&query=Zanzibar+Watersports+Nungwi", "badge": "PADI", "tags": ["Full PADI range", "Leven Bank", "Tumbatu"], "productTags": ["PADI"], "hours": "Daily, dawn departures for the deep sites", "why": "A PADI centre that runs courses, double dives for certified divers, full-day trips to the Mnemba atoll and trips to Leven Bank, a deep bank in the Pemba Channel with strong currents that only experienced divers should do. It works from the Kendwa Rocks beach, which makes it the nearest dive desk if you are staying there. Mnemba carries a separate conservation fee of about US$25 per foreign adult, paid on top of the dive.", "address": "Kendwa Beach, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.728396, "lng": 39.292284, "hook": "PADI dive and water-sports centre on the north coast, running trips to Leven Bank and Mnemba.", "verdict": "The convenient option if you are staying in Kendwa; the deep-site briefing is the thing to listen to.", "caveat": "Leven Bank is a strong-current, experienced-divers-only site and can only be dived on certain tides. Do not book it as your first dive of a trip.", "price_range": "Standard Zanzibar dive rates; Mnemba carries a US$10 per-person conservation fee", "reservation": "Book the day before", "best_time": "Morning departures", "web": "https://zanzibarwatersports.com/"},
    {"id": "spanish-dancer", "cat": "logistics", "tier": "plenty", "priority": 29, "name": "Spanish Dancer Divers", "short": "Spanish Dancer", "neighborhood": "Nungwi · on the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Spanish+Dancer+Divers+Nungwi+Zanzibar", "badge": "PADI5", "tags": ["PADI 5-star since 2001", "Four languages", "Mnemba, Leven, Tumbatu"], "productTags": ["PADI 5★", "Since 2001"], "hours": "Daily", "why": "PADI's directory calls it one of the first dive centres on Zanzibar, with a twenty-year safety record, and rates it a 5 Star Dive Resort. Courses run in English, Spanish, French and German. That length of time in the same water is the useful thing: a desk that has dived these sites for two decades can tell you which day and tide suits the site you have in mind, and which sites to skip.", "address": "Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.731894, "lng": 39.291138, "hook": "A PADI 5 Star dive resort in Nungwi, teaching in English, Spanish, French and German.", "verdict": "The most experienced dive operation on the north tip, and the one to ask about conditions before you commit.", "caveat": "Mnemba trips carry the conservation-area fee on top of the dive price.", "price_range": "Standard rates + US$10 Mnemba conservation fee", "reservation": "Book ahead in season", "best_time": "Morning", "web": "https://www.divinginzanzibar.com/", "hot_this_month": "The humpbacks are leaving: sightings tail off through October and are luck by November."},
    {"id": "nungwi-dhow-yard", "cat": "market", "tier": "plenty", "priority": 31, "name": "The Nungwi dhow yards", "short": "Dhow yards", "neighborhood": "Nungwi · the working beach north of the hotels", "maps": "https://www.google.com/maps/search/?api=1&query=Nungwi+dhow+Zanzibar", "badge": "BOATYARD", "tags": ["Working yard, not a museum", "Mango and hardwood", "Ask before photographing"], "productTags": ["Dhow yard"], "hours": "Daylight, most days — it is a workplace, not an attraction with hours", "why": "Nungwi is known across Zanzibar as the place the dhows are built, and the work happens in the open on the beach: shipwrights turning rough timber into ocean-going hulls with hand tools and methods passed down through families. There is no ticket and no viewing platform. It is a place of work, so watch from a respectful distance, ask before photographing anyone, and keep off the hulls.", "address": "Nungwi beach, north of the hotel line", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.723773, "lng": 39.295867, "hook": "Nungwi's beach boatyards, where dhows are still built by hand on the open sand.", "person": "The Nungwi shipwrights", "signature": "Watching a ngalawa hull being dug from a single mango trunk", "verdict": "The most alive craft on this island and the reason to walk north out of the bar strip at all.", "caveat": "This is a workplace. Ask before photographing; do not climb on the boats; tip the guide if you take one.", "price_range": "Free to watch; a guide expects a tip", "reservation": "None", "best_time": "Morning, before the heat"},
    {"id": "mnarani", "cat": "market", "tier": "plenty", "priority": 32, "name": "Mnarani Marine Turtles Conservation Pond", "short": "Mnarani", "neighborhood": "Nungwi · by the lighthouse, north-east of the village", "maps": "https://www.google.com/maps/search/?api=1&query=Mnarani+Marine+Turtles+Conservation+Pond+Nungwi", "badge": "TURTLES", "tags": ["Community-run since 1993", "Green + hawksbill", "February release"], "productTags": ["Turtles", "Since 1993"], "hours": "Daytime, daily", "why": "In 1993 the people of Nungwi, with help from conservation groups and marine biologists, turned a tidal lagoon near the lighthouse into a pool for sea turtles. That is where the name comes from: Mnarani means 'at the lighthouse'. Visitors stand on a wooden platform and feed seaweed to the turtles, and swimming with them is sometimes allowed. Entry is about US$10.", "address": "Mnarani, Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.72249, "lng": 39.30271, "hook": "A tidal turtle pool by the Nungwi lighthouse, opened by the village in 1993; about US$10 to enter.", "person": "Founded 1993 by Nungwi villagers and conservationists", "signature": "The February release — rehabilitated turtles going back through the surf", "verdict": "The honest option of the two turtle ponds here: community-founded, tidally flushed, with an actual annual release rather than a website paragraph.", "caveat": "It is still a captive pond with paying visitors, and the animals are handled. If that is a line for you, do not go — watch for turtles on a Mnemba dive instead.", "price_range": "Small entry fee, cash", "reservation": "None", "best_time": "Morning"},
    {"id": "baraka-aquarium", "cat": "market", "tier": "plenty", "priority": 33, "name": "Baraka Natural Aquarium", "short": "Baraka Aquarium", "neighborhood": "Nungwi · Mkunguni", "maps": "https://www.google.com/maps/search/?api=1&query=Baraka+Natural+Aquarium+Nungwi", "badge": "DISPUTED", "tags": ["US$10 per activity", "08:00–18:00 daily", "Contested"], "productTags": ["Turtles"], "hours": "Daily 08:00–18:00", "why": "Its own pages say it exists to rescue and rehabilitate turtles and return them to the sea, and tour sellers market it as a chance to feed and swim with them in a natural lagoon pool near Mnarani Cottages. Visitor accounts dispute this: small crowded pools, animals handled, and no evidence of releases when asked. We could not settle the argument, so read the accounts before you buy a ticket from a beach seller.", "address": "Mkunguni, Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.724447, "lng": 39.303474, "hook": "A turtle lagoon in Nungwi that sells swims and feeding; its welfare claims are disputed by visitors.", "verdict": "Contested, and we could not settle it. If you want turtles, go to Mnarani, or dive Mnemba and see them wild.", "caveat": "⚠ Animal-welfare concerns are substantial and repeated in visitor accounts. Read them before you buy a ticket.", "price_range": "US$10 per activity", "reservation": "None", "best_time": "—", "web": "https://barakaaquarium.com/"},
    {"id": "ras-nungwi-lighthouse", "cat": "mainland", "tier": "plenty", "priority": 34, "name": "Ras Nungwi Lighthouse", "short": "The lighthouse", "neighborhood": "Nungwi · the northern point itself", "maps": "https://www.google.com/maps/search/?api=1&query=Nungwi+Lighthouse+Zanzibar", "badge": "LIGHT", "tags": ["14 m tower", "Range 13 nm", "No public entry"], "productTags": [], "hours": "Exterior only — it is an operating aid to navigation, not a museum", "why": "Ras Nungwi, which old charts call Hog Point, is the northern tip of Unguja, and a light has marked it since the 1880s. The tower there now is a white square stone tower in three stages, built in 1926: 14 metres tall with a focal height of 18 metres, and its white flash reaches 13 nautical miles. The Zanzibar Ports Corporation still runs it as a working light, so you see it from outside only.", "address": "Ras Nungwi, Kaskazini A", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.722305, "lng": 39.303306, "hook": "Unguja's oldest lighthouse, a white stone tower lit in 1926 at the island's northern point.", "signature": "Standing at the point at dusk as the light comes on", "verdict": "Five minutes of your day and the best orientation on the whole cape — everything in this guide is arranged around this corner.", "caveat": "No public access to the tower. Sources disagree on whether the first station was 1881 or 1886.", "price_range": "Free", "reservation": "None", "best_time": "Dusk"},
    {"id": "kendwa-beach", "cat": "mainland", "tier": "plenty", "priority": 35, "name": "Kendwa Beach", "short": "Kendwa Beach", "neighborhood": "Kendwa · the whole west-facing sand", "maps": "https://www.google.com/maps/search/?api=1&query=Kendwa+Beach+Zanzibar", "badge": "ALLTIDE", "tags": ["Swimmable at any tide", "West-facing", "3 km from the point"], "productTags": ["All tides", "Sunset side"], "hours": "Always", "why": "Along most of Zanzibar's east and south-east coast the sea goes out a long way at low tide and you plan swims around the tide table. Kendwa, on the north-west coast, shelves quickly, so the water is deep enough to swim in for most of the day whatever the tide is doing. It also faces west, so you can stay in the water until the sun goes down.", "address": "Kendwa, Kaskazini A, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.754416, "lng": 39.292008, "hook": "A west-facing beach on Unguja where the sea stays close at low tide, so you can swim most of the day.", "signature": "A swim at low water, which almost nowhere else on this island allows", "verdict": "Not a matter of taste: this is a bathymetric fact and it is why you are here rather than at Paje.", "caveat": "Public beach — the hawker traffic is constant, and it is a Muslim island: cover up walking off the sand.", "price_range": "Free", "reservation": "None", "best_time": "Low water in the late afternoon"},
    {"id": "tumbatu", "cat": "mainland", "tier": "plenty", "priority": 37, "name": "Tumbatu Island", "short": "Tumbatu", "neighborhood": "Offshore, west · the island Kendwa looks at", "maps": "https://www.google.com/maps/search/?api=1&query=Tumbatu+Zanzibar", "badge": "ISLAND", "tags": ["Permit from the elders required", "Kitumbatu dialect", "12th-c. ruins at Makutani"], "productTags": ["UNESCO 2000"], "hours": "Daylight crossings from Mkokotoni; permitted visits only", "why": "The long low island on Kendwa's western horizon is the home of the Watumbatu, reputed the best sailors on this coast, with their own dialect and their own boats. It is the shape the sun goes down beside, seen from every bar on Kendwa sand, and the one place on this horizon that is not for visiting on a whim: the card in Sights explains how it is done.", "address": "Tumbatu, Kaskazini A, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.812684, "lng": 39.221289, "hook": "The island off Kendwa with 12th-century stone-town ruins, visited only with the elders' permission.", "person": "The Watumbatu", "signature": "The Shirazi mosque ruins in the forest at Makutani", "verdict": "The most historically important thing visible from Kendwa sand, and the one you are least entitled to walk into.", "caveat": "⚠ Not an open destination. Anyone not from Tumbatu — including Zanzibaris — needs written permission from the village elders, and visits go with an approved local guide who asks for that blessing first. Do not hire a boat and turn up. The island's reputation for keeping outsiders out is earned and deliberate.", "price_range": "Guided cultural visit, arranged in advance", "reservation": "Permit + approved guide, arranged days ahead through Mkokotoni", "best_time": "Morning crossing on a settled tide"},
    {"id": "mangapwani-cave", "cat": "mainland", "tier": "plenty", "priority": 38, "name": "Mangapwani coral cave & slave chamber", "short": "Mangapwani", "neighborhood": "West coast · about 20 km north of Stone Town", "maps": "https://www.google.com/maps/search/?api=1&query=Mangapwani+Zanzibar", "badge": "HISTORY", "tags": ["~US$5 entry", "Two sites, 1 km apart", "Take a guide"], "productTags": [], "hours": "Daylight", "why": "On the west-coast road between Kendwa and Stone Town, a natural cave with fresh water at the bottom and, nearby, a cell cut into the coral to hold captives after the trade was banned. An hour here is the part of the spice story the plantations leave out; stop on the drive south and take a guide.", "address": "Mangapwani, Kaskazini B, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -5.989825, "lng": 39.195925, "hook": "A coral cave with a freshwater pool, and nearby a rock-cut cell used to hold slaves after abolition.", "signature": "The steps down into the chamber", "verdict": "Go, and take a guide who will tell it properly. This is the counterweight to every clove-scented spice tour on the island.", "caveat": "Sombre, unlit and low-ceilinged. Entry around US$5 for a foreign adult; small notes. Not a place for a casual half hour between beaches.", "price_range": "~US$5 foreign adult", "reservation": "None; a guide is worth it", "best_time": "Morning, on the way to or from Stone Town"},
    {"id": "stone-town", "cat": "mainland", "tier": "plenty", "priority": 39, "name": "Stone Town", "short": "Stone Town", "neighborhood": "South-west · about 56 km from Kendwa, roughly 1 h 15 by road", "maps": "https://www.google.com/maps/search/?api=1&query=Stone+Town+Zanzibar", "badge": "UNESCO", "tags": ["UNESCO World Heritage 2000", "1 h 15 from Kendwa", "The day trip"], "productTags": ["UNESCO 2000"], "hours": "Always; the night market from about 18:00", "why": "Stone Town was inscribed by UNESCO in 2000 as a Swahili trading town built of coral stone, and almost everything on a north-coast menu passed through its port first. A single day can follow the food: Darajani market, opened in 1904, in the morning; the cathedral built on the last open slave market at midday; the Forodhani gardens when the grills light at dusk; then a rooftop dinner above the town before the drive back north.", "address": "Stone Town, Mjini Magharibi, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -6.162653, "lng": 39.189655, "hook": "The UNESCO-listed old town an hour and a quarter south of Kendwa: market, memorial, night food, rooftops.", "signature": "Darajani in the morning, Forodhani at dusk, a rooftop after dark", "verdict": "A full day or don't bother. The drive each way eats three hours of daylight.", "caveat": "Do not attempt it as a half-day from Kendwa; the road is slow and you will see a car park and a curio shop.", "price_range": "Transfer roughly US$50–70 each way by private car; shared transfers less", "reservation": "Arrange the car the day before", "best_time": "Leave Kendwa by 08:00; be at Forodhani by 18:00"},
    {"id": "mnemba", "cat": "mainland", "tier": "plenty", "priority": 45, "name": "Mnemba Atoll", "short": "Mnemba", "neighborhood": "Offshore, north-east · reached from Nungwi or Matemwe", "maps": "https://www.google.com/maps/search/?api=1&query=Mnemba+Zanzibar", "badge": "ATOLL", "tags": ["US$10 conservation fee", "Island is private", "Reef restoration in progress"], "productTags": ["PADI"], "hours": "Day trips from the north tip", "why": "The island is private, run as an &Beyond lodge, and day boats cannot land, so the trip is entirely about the water around it, which is a protected marine area with its own entry fee. After the February 2024 global bleaching hit the reef, &Beyond and Wild Impact began fixing hexagonal steel 'reef stars', built by people from nearby villages, onto the coral rubble and planting them with nursery-grown fragments.", "address": "Mnemba Atoll, off north-east Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.819608, "lng": 39.383722, "hook": "A private atoll off Unguja's north-east coast, ringed by a marine conservation area you reach by boat.", "signature": "A drift over the atoll edge with green turtles below you", "verdict": "The place to see turtles honestly — wild, unfed and not in a pond.", "caveat": "⚠ You cannot land on the island: it is private, and boats that promise a beach landing are selling you something they cannot deliver. The US$10 conservation fee is on top of the trip price.", "price_range": "Dive or snorkel trip + US$10 per-person conservation fee", "reservation": "Through any north-tip dive centre, day before", "best_time": "Early departure, before the wind gets up"},
    {"id": "leven-bank", "cat": "mainland", "tier": "plenty", "priority": 46, "name": "Leven Bank", "short": "Leven Bank", "neighborhood": "Offshore, north · the Pemba Channel", "maps": "https://www.google.com/maps/search/?api=1&query=Leven+Bank+Nungwi+Zanzibar", "badge": "DEEP", "tags": ["Experienced divers only", "Strong current", "Certain tides only"], "productTags": ["PADI"], "hours": "Tide-dependent departures", "why": "Leven Bank is a seamount out in the Pemba Channel whose top sits about fourteen metres down, and divers with the right qualifications go to around fifty. The current across it is strong enough that the north-tip centres pick the day by conditions, not by the calendar, and take only experienced divers. Those who go come back describing large groupers, moray eels, tuna and barracuda, and sometimes rays or dolphins.", "address": "Pemba Channel, north of Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "hook": "A submerged mountain in the Pemba Channel north of Nungwi, an advanced drift dive in strong current.", "signature": "The drop past the shoulder into the channel current", "verdict": "The best dive reachable from this beach, and the one most likely to be cancelled — take the cancellation as professionalism, not bad luck.", "caveat": "⚠ Experienced divers only, strong current, and genuinely tide-gated. Do not make it your first dive of a trip. The name most likely honours HMS Leven, which surveyed this coast in the 1820s — but we could not confirm the naming from a primary source, so we are not asserting it.", "price_range": "Premium dive rate", "reservation": "Book on a tide, not on a date", "best_time": "Whatever tide the centre says", "hot_this_month": "The kusi drops through October: calm water and good visibility, still tide-gated."},
    {"id": "old-fort", "cat": "mainland", "tier": "plenty", "priority": 48, "name": "The Old Fort (Ngome Kongwe)", "short": "Old Fort", "neighborhood": "Stone Town · seafront, beside Forodhani", "maps": "https://www.google.com/maps/search/?api=1&query=Old+Fort+Zanzibar", "badge": "FORT", "tags": ["Free to enter the courtyard", "Beside Forodhani", "Craft stalls"], "productTags": ["UNESCO 2000"], "hours": "Daytime; courtyard events in the evening", "why": "The Omani rulers of Zanzibar built the fort on the site of an earlier Portuguese church, and it still stands at the head of the seafront beside Forodhani. In 1994 part of the courtyard became an open-air amphitheatre, which for 22 years hosted the Sauti za Busara music festival until it outgrew the walls and moved to Mnazi Mmoja in 2026. The courtyard is free and opens straight onto Forodhani.", "address": "Mizingani Road, Stone Town", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -6.161359, "lng": 39.189065, "hook": "The Omani fort on Stone Town's seafront, its courtyard free to enter and its amphitheatre used for shows.", "verdict": "Twenty minutes, free, and it orients the whole seafront.", "caveat": "The stalls inside are curio stalls; the building is the point.", "price_range": "Free courtyard", "reservation": "None", "best_time": "Late afternoon, before Forodhani"},
    {"id": "anglican-cathedral", "cat": "mainland", "tier": "plenty", "priority": 49, "name": "Christ Church Cathedral & the slave-market memorial", "short": "Christ Church", "neighborhood": "Stone Town · Mkunazini", "maps": "https://www.google.com/maps/search/?api=1&query=Christ+Church+Cathedral+Stone+Town+Zanzibar", "badge": "MEMORIAL", "tags": ["Built on the slave market", "Underground chambers", "Entry fee"], "productTags": ["UNESCO 2000"], "hours": "Daytime", "why": "Sultan Barghash closed the public slave market under British pressure in 1873, and missionaries built Christ Church on the same ground, opening it in 1879. A heritage centre at the gate, opened in 2016, tells the trade's story before you reach the cramped holding chambers. Outside, five figures by the Swedish artist Clara Sörnäs, installed in 1998, stand in a pit, chained at the neck.", "address": "Mkunazini, Stone Town", "phone": "—", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -6.162908, "lng": 39.192572, "hook": "The cathedral on the site of Zanzibar's last open slave market, with holding chambers and a memorial.", "verdict": "Non-optional if you are going to enjoy the cloves.", "caveat": "Entry fee; the chambers are low, dark and deliberately hard.", "price_range": "Small entry fee", "reservation": "None", "best_time": "Morning"},
    {"id": "flame-tree", "cat": "shop", "tier": "plenty", "priority": 53, "name": "Flame Tree Cottages", "short": "Flame Tree", "neighborhood": "Nungwi · the quiet north-west end of the beach, in a garden", "maps": "https://www.google.com/maps/search/?api=1&query=Flame+Tree+Cottages+Nungwi+Zanzibar", "badge": "GARDEN", "tags": ["Garden cottages", "Quiet", "Restaurant on site"], "productTags": [], "hours": "Breakfast through dinner", "why": "Flame Tree is a small hotel of individually styled cottages, with Zanzibari beds and Swahili wood furniture, set in a garden of coconut palms, frangipani and the red-flowering flame trees it is named for. It sits at the quieter north-west end of Nungwi, facing west over the water for the sunset, and has two garden restaurants and tables set up on the beach for dinner.", "address": "Nungwi, Kaskazini A", "phone": "+255 712 530 776", "status": "confirmed", "statusChecked": "2026-10-07", "lat": -5.72529, "lng": 39.293719, "hook": "Garden cottages at the quiet north-west end of Nungwi beach, with restaurants open onto the sand.", "verdict": "Pleasant and quiet; a shade address rather than a food one.", "caveat": "Small and quiet by design; at the north-west end, so the sunset is in front of you.", "price_range": "Low-mid", "reservation": "None", "best_time": "Middle of the day", "web": "http://www.flametreecottages.com/"},
    {"id": "dhow-course", "cat": "logistics", "tier": "plenty", "priority": 71, "name": "The dhow-building course, Nungwi", "short": "Dhow course", "neighborhood": "Nungwi · in the working boatyards on the beach", "maps": "https://www.google.com/maps/search/?api=1&query=Nungwi+dhow+Zanzibar", "badge": "CRAFT", "tags": ["Taught in the working yard", "Open to outsiders", "Book ahead"], "productTags": ["Dhow yard"], "hours": "Arranged in advance; daytime, alongside the yard's own working hours", "why": "The one place on the island where an outsider can learn a living craft from the people who practise it: placements in a working Nungwi boatyard, arranged through World Unite!, with instruction in English every day and the rest of the day spent on hulls that will go to sea.", "address": "The Nungwi boatyards, Kaskazini A, Unguja", "phone": "—", "status": "unverified", "statusChecked": "", "hook": "A 1-12 week course in Nungwi's boatyards, taught by a dhow builder, booked through World Unite!.", "person": "Mr. Mponda, the dhow builder named on the course's own page, who learned the trade from his father", "signature": "Being handed an adze in a working yard and shown what it is actually for", "verdict": "The rarest kind of place: a living craft whose masters teach it in situ, and you can enrol as an outsider. Everything else on this island that calls itself a craft experience is a demonstration.", "caveat": "⚠ Arranged in advance through the placement organiser, not booked at the gate — and it is a workplace, not a school building, so the schedule bends to the yard's work, not yours. Confirm current availability and the fee directly before you travel; we could not load the operator's own page from here (it refused the request), so the details above come from its published accounts rather than a live price list.", "price_range": "Placement fee, quoted on application — confirm directly", "reservation": "Arranged in advance through World Unite!", "best_time": "Mornings, before the heat stops the yard", "web": "https://www.world-unite.de/en/courses/zanzibar/dhow-boat-building-sailing-ship-construction"},
    {"id": "mwani-zanzibar", "web": "https://mwanizanzibar.com/", "cat": "market", "tier": "plenty", "priority": 72, "name": "Mwani Zanzibar", "short": "Mwani Zanzibar", "neighborhood": "Paje · east coast, about 1 h 30 from Kendwa", "maps": "https://www.google.com/maps/search/?api=1&query=Mwani+Zanzibar+Paje", "badge": "SEAWEED", "tags": ["Women's production workshop", "Morning visits at low tide", "Buy at the asking price"], "productTags": ["Spice"], "hours": "Morning visits, timed to low tide", "why": "Mwani Zanzibar, once called the Seaweed Center, turns the spiny red seaweed Eucheuma denticulatum that women farm in the Paje shallows into soaps, scrubs and oils, wrapping the soap in banana leaf. A visit of about ninety minutes, around US$10, starts on the beach farm, which is only reachable at low tide, and ends in the centre where the bars are cut and packed.", "address": "Paje, Kusini, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "hook": "A seaweed skincare maker in Paje, formerly the Seaweed Center; 90-minute tours of the farm and workshop.", "person": "The Mwani Mamas, salaried and on permanent contracts", "signature": "Low tide with the growers, then the workshop where it becomes soap", "verdict": "The most honest place on this island to spend money on a souvenir, because you can see exactly whose wage it becomes.", "caveat": "⚠ ET bar, honestly: this is a **guided visit to a working production floor, not an enrolment**. You watch and you buy; you do not learn the craft as a student. It clears at-the-source and dedicated-to-the-craft, and it fails open-enrolment. Listed for what it is. Also 1 h 30 from Kendwa on the far coast — a day, not a detour.", "price_range": "Visit plus whatever you buy — do not bargain the products down", "reservation": "Arrange the morning ahead; the timing follows the tide", "best_time": "Morning, on a low tide"},
    {"id": "kuza-cave", "cat": "market", "tier": "plenty", "priority": 73, "name": "Kuza Cave Culture Centre", "short": "Kuza Cave", "neighborhood": "Jambiani · south-east coast, about 1 h 45 from Kendwa", "maps": "https://www.google.com/maps/search/?api=1&query=Kuza+Cave+Jambiani+Zanzibar", "badge": "CULTURE", "tags": ["Swahili cooking lessons", "Coral cavern", "Bookable"], "productTags": ["Swahili"], "hours": "Daytime; lessons booked in advance", "why": "Kuza Cave is a collapsed limestone chamber in Jambiani with a pool of clear groundwater at the bottom, closer to a Yucatan cenote than a show cave, and it is managed with the traditional owners in Kibigija Village. Around it runs a culture centre: a Swahili cooking lesson every day at 11:30 for US$30, two hours that end with eating what you cooked.", "address": "Jambiani, Kusini, Unguja", "phone": "—", "status": "confirmed", "statusChecked": "2026-08-22", "lat": -6.303801, "lng": 39.533398, "hook": "A culture centre around a cenote-like cave in Jambiani, with a daily 11:30 Swahili cooking lesson.", "signature": "A Swahili cooking lesson — pressing your own coconut on the mbuzi", "verdict": "The best structured cooking teaching on Unguja, and the fact that it sits inside a village culture centre rather than a hotel is the whole reason to prefer it.", "caveat": "⚠ ET bar: no single named master is published, so it clears three bars and not the first. And it is on the opposite corner of the island — about 1 h 45 each way from Kendwa. Book before you drive.", "price_range": "Per-lesson fee, booked in advance", "reservation": "Book ahead", "best_time": "Morning lesson, so you eat what you cook at lunch", "web": "https://www.kuzacave.com/product/swahili-cooking-lesson/"}
  ];
